    chart(yearly)
      .flow(scatter({ x: "year", y: "count" }))
      .mark(
        circle({
          r: 4,
          fill: "series",
          stroke: "white",
          opacity: (d) => (d.year === focus() ? 1 : 0),
        }).name("pts")
      )
  )
  // the box: the points at the focused year, as one group
  .layer(
    chart(selectAll("pts"))
      .flow(
        filter((pt) => pt.datum[0].year === focus()),
        group({ by: "year" })
      )
      .mark((pts) => {
        const rows = pts
          .map((pt) => pt.datum[0])
          .sort((a, b) => b.count - a.count);
        const anchor = enclose(
          { padding: 6, fill: "none", stroke: "none" },
          pts
        ).zOrder(1);
        return beside(
          anchor,
          box(
            table(
              rows.map((r) => [r.series, thousands(r.count)]),
              { title: String(rows[0].year) }
            )
          ),
          { side: rows[0].year > 2005 ? "left" : "right" } // picked by hand
        );
      })
  );

